/// VYRO AI â€” Firebase Service
///
/// Initializes Firebase and provides access to Auth, Firestore and Storage.
/// Firebase configuration is injected via google-services.json (Android) and
/// GoogleService-Info.plist (iOS), generated by `flutterfire configure`.
/// No API keys are hardcoded here.
///

import 'dart:io';
import 'dart:typed_data';
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:firebase_core/firebase_core.dart';
import 'package:vyro_ai/firebase_options.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_storage/firebase_storage.dart';

class FirebaseService {
  FirebaseService._();
  static final FirebaseService instance = FirebaseService._();

  FirebaseAuth get auth => FirebaseAuth.instance;
  FirebaseFirestore get firestore => FirebaseFirestore.instance;
  FirebaseStorage get storage => FirebaseStorage.instance;

  bool get isInitialized => Firebase.apps.isNotEmpty;

  Future<void> initialize() async {
    if (Firebase.apps.isNotEmpty) return;
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
    // Persistent login: on the web the auth session is kept in IndexedDB
    // (LOCAL) so closing the browser/tab does not sign the user out —
    // reopening restores the session from Firebase Auth automatically.
    // Android/iOS/desktop persist the session natively by default.
    if (kIsWeb) {
      try {
        await auth.setPersistence(Persistence.LOCAL);
      } catch (_) {
        // Older web setups may not support setPersistence — the default
        // IndexedDB persistence already keeps the session.
      }
    }
  }

  /// Sign in anonymously (guest mode) â€” no credentials stored.
  Future<UserCredential> signInAnonymously() async {
    return await auth.signInAnonymously();
  }

  /// Sign in with email & password.
  Future<UserCredential> signInWithEmailPassword(
    String email,
    String password,
  ) async {
    return await auth.signInWithEmailAndPassword(
      email: email,
      password: password,
    );
  }

  /// Create account with email & password.
  Future<UserCredential> createWithEmailPassword(
    String email,
    String password,
  ) async {
    return await auth.createUserWithEmailAndPassword(
      email: email,
      password: password,
    );
  }

  /// Send password reset email.
  Future<void> sendPasswordReset(String email) async {
    await auth.sendPasswordResetEmail(email: email);
  }

  Future<void> signOut() async {
    await auth.signOut();
  }

  Stream<User?> get authStateChanges => auth.authStateChanges();

  // ============================================================================
  // FIRESTORE REFERENCE HELPERS
  // ============================================================================

  /// users/{uid} â€” main user account document
  DocumentReference userDoc(String uid) => firestore.collection('users').doc(uid);
  CollectionReference usersCollection() => firestore.collection('users');

  /// user_profiles/{uid} â€” extended profile data
  DocumentReference userProfileDoc(String uid) =>
      firestore.collection('user_profiles').doc(uid);
  CollectionReference userProfilesCollection() =>
      firestore.collection('user_profiles');

  /// user_projects/{projectId} â€” user's editable projects
  DocumentReference userProjectDoc(String projectId) =>
      firestore.collection('user_projects').doc(projectId);
  CollectionReference userProjectsCollection() =>
      firestore.collection('user_projects');
  Query<Map<String, dynamic>> userProjectsByUser(String uid) =>
      firestore.collection('user_projects').where('userId', isEqualTo: uid);

  /// generated_stories/{storyId} â€” AI generated stories
  DocumentReference generatedStoryDoc(String storyId) =>
      firestore.collection('generated_stories').doc(storyId);
  CollectionReference generatedStoriesCollection() =>
      firestore.collection('generated_stories');
  Query<Map<String, dynamic>> generatedStoriesByUser(String uid) =>
      firestore.collection('generated_stories').where('userId', isEqualTo: uid);

  /// generated_videos/{videoId} â€” AI generated videos
  DocumentReference generatedVideoDoc(String videoId) =>
      firestore.collection('generated_videos').doc(videoId);
  CollectionReference generatedVideosCollection() =>
      firestore.collection('generated_videos');
  Query<Map<String, dynamic>> generatedVideosByUser(String uid) =>
      firestore.collection('generated_videos').where('userId', isEqualTo: uid);

  /// generated_images/{imageId} â€” AI generated images
  DocumentReference generatedImageDoc(String imageId) =>
      firestore.collection('generated_images').doc(imageId);
  CollectionReference generatedImagesCollection() =>
      firestore.collection('generated_images');
  Query<Map<String, dynamic>> generatedImagesByUser(String uid) =>
      firestore.collection('generated_images').where('userId', isEqualTo: uid);

  /// user_credits/{uid} â€” user credit balance
  DocumentReference userCreditsDoc(String uid) =>
      firestore.collection('user_credits').doc(uid);
  CollectionReference userCreditsCollection() =>
      firestore.collection('user_credits');

  /// transactions/{transactionId} â€” credit/purchase transactions
  DocumentReference transactionDoc(String transactionId) =>
      firestore.collection('transactions').doc(transactionId);
  CollectionReference transactionsCollection() =>
      firestore.collection('transactions');
  Query<Map<String, dynamic>> transactionsByUser(String uid) =>
      firestore.collection('transactions').where('userId', isEqualTo: uid);

  /// login_activity/{activityId} — login history
  DocumentReference loginActivityDoc(String activityId) =>
      firestore.collection('login_activity').doc(activityId);
  CollectionReference loginActivityCollection() =>
      firestore.collection('login_activity');
  Query<Map<String, dynamic>> loginActivityByUser(String uid) =>
      firestore.collection('login_activity').where('userId', isEqualTo: uid);

  // ============================================================================
  // USER-SUBCOLLECTION HELPERS (master structure: users/{uid}/generations, ...)
  // ============================================================================
  // The top-level collections above remain the primary store used by existing
  // screens (preserves existing records). These per-user subcollections mirror
  // the target structure users/{uid}/generations/{generationId} and
  // users/{uid}/transactions/{transactionId} for features that need it.

  /// users/{uid}/generations/{generationId} — AI generation history
  CollectionReference userGenerations(String uid) =>
      firestore.collection('users').doc(uid).collection('generations');
  DocumentReference userGenerationDoc(String uid, String generationId) =>
      firestore
          .collection('users')
          .doc(uid)
          .collection('generations')
          .doc(generationId);

  /// users/{uid}/transactions/{transactionId} — payment/credit history
  CollectionReference userTransactions(String uid) =>
      firestore.collection('users').doc(uid).collection('transactions');
  DocumentReference userTransactionDoc(String uid, String transactionId) =>
      firestore
          .collection('users')
          .doc(uid)
          .collection('transactions')
          .doc(transactionId);

  // ============================================================================
  // LEGACY COLLECTION HELPERS (for existing providers)
  // ============================================================================

  /// videos/{uid} sub-collection (legacy)
  CollectionReference videosCollection(String uid) =>
      firestore.collection('users').doc(uid).collection('videos');

  /// aiJobs/{uid} sub-collection (legacy)
  CollectionReference jobsCollection(String uid) =>
      firestore.collection('users').doc(uid).collection('aiJobs');

  /// projects/{uid} sub-collection (legacy)
  CollectionReference projectsCollection(String uid) =>
      firestore.collection('users').doc(uid).collection('projects');

  /// templates collection (legacy)
  CollectionReference templatesCollection() =>
      firestore.collection('templates');

  // ============================================================================
  // FIREBASE STORAGE REFERENCE HELPERS
  // ============================================================================

  /// Storage path for profile pictures: users/{uid}/profile/profile.jpg
  Reference profilePictureRef(String uid) =>
      storage.ref().child('users/$uid/profile/profile.jpg');

  /// Storage path for character reference images: users/{uid}/characters/{fileName}
  Reference characterRef(String uid, String fileName) =>
      storage.ref().child('users/$uid/characters/$fileName');

  /// Storage path for AI-generated story images: users/{uid}/stories/{storyId}/{fileName}
  Reference storyImageRef(String uid, String storyId, String fileName) =>
      storage.ref().child('users/$uid/stories/$storyId/$fileName');

  /// Storage path for AI-generated story audio: users/{uid}/stories/{storyId}/{fileName}
  Reference storyAudioRef(String uid, String storyId, String fileName) =>
      storage.ref().child('users/$uid/stories/$storyId/$fileName');

  /// Storage path for generated videos: users/{uid}/videos/{videoId}/{fileName}
  Reference videoRef(String uid, String videoId, String fileName) =>
      storage.ref().child('users/$uid/videos/$videoId/$fileName');

  /// Storage path for video thumbnails: users/{uid}/videos/{videoId}/thumb/{fileName}
  Reference videoThumbnailRef(String uid, String videoId, String fileName) =>
      storage.ref().child('users/$uid/videos/$videoId/thumb/$fileName');

  /// Storage path for generated images: users/{uid}/images/{imageId}/{fileName}
  Reference imageRef(String uid, String imageId, String fileName) =>
      storage.ref().child('users/$uid/images/$imageId/$fileName');

  /// Upload a file to storage and return the download URL.
  Future<String> uploadFile(Reference ref, File file, {String? contentType}) async {
    final sett = contentType != null
        ? SettableMetadata(contentType: contentType)
        : null;
    final snapshot = await ref.putFile(file, sett);
    return await snapshot.ref.getDownloadURL();
  }

  /// Upload bytes to storage and return the download URL.
  Future<String> uploadBytes(Reference ref, Uint8List data, {String? contentType}) async {
    final sett = contentType != null
        ? SettableMetadata(contentType: contentType)
        : null;
    final snapshot = await ref.putData(data, sett);
    return await snapshot.ref.getDownloadURL();
  }

  /// Delete a file from storage.
  Future<void> deleteFile(Reference ref) async {
    await ref.delete();
  }

  /// Get download URL for a storage reference (if file exists).
  Future<String?> getDownloadUrl(Reference ref) async {
    try {
      return await ref.getDownloadURL();
    } catch (_) {
      return null;
    }
  }
}
